using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckCurling {
public sealed class CurlingSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();CurlingMatch m;Keyboard keyboard;InputSettings original,probe;string folder;bool done,error;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsCurling")<0)return;var g=new GameObject("Curling native rules/physical validation");DontDestroyOnLoad(g);g.AddComponent<CurlingSmoke>();}
 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("CurlingEvidence");Directory.CreateDirectory(folder);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Curling software keyboard");InputSystem.QueueStateEvent(keyboard,new KeyboardState());Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string s,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){error=true;records.Add("ERROR "+s);}}void Check(bool b,string label){if(!b)throw new Exception(label);records.Add("PASS "+label);Debug.Log("CURLING_NATIVE_PASS "+label);}void Note(string label){records.Add(label);Debug.Log("CURLING_NATIVE_EVIDENCE "+label);}
 IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}IEnumerator Wait(Func<bool> predicate,float seconds,string label){float end=Time.realtimeSinceStartup+seconds;while(!predicate()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+label+" end="+m.End+" delivery="+m.Delivery+" phase="+m.Phase+" pos="+m.Current.truck.body.position+" velocity="+m.Current.truck.body.linearVelocity);yield return null;}}
 void Update(){if(done)return;try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator child){steps.Push(child);continue;}return;}Finish(error?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError(e);Finish(2);}}
 void Finish(int code){done=true;Time.timeScale=1;if(keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(probe);File.WriteAllLines(Path.Combine(folder,"results.txt"),records);Application.Quit(code);}void Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));}
 IEnumerator Run(){yield return Delay(.5f);SceneManager.LoadScene("TruckCurling");yield return Delay(.5f);m=FindAnyObjectByType<CurlingMatch>();Check(m!=null&&m.stones.Length==16,"saved16 stone scene");m.teamA=m.teamB=1;m.option=0;m.setup.count=2;m.AllBots();Check(m.StartMatch(),"first physical AI draw starts");yield return Wait(()=>m.Phase==CurlingPhase.Slide,8,"release");Check(!m.Current.truck.Powered&&m.Current.truck.body.linearVelocity.z>2,"release disables engine and preserves world momentum");Capture("cab-slide");yield return Delay(.2f);m.Pause();var p=m.Current.truck.body.position;var v=m.Current.truck.body.linearVelocity;yield return Delay(.3f);Check(m.Current.truck.body.position==p&&m.Current.truck.body.linearVelocity==v,"pause preserves sliding momentum and bodies");m.Resume();Time.timeScale=3;yield return Wait(()=>m.Phase==CurlingPhase.DeliveryResult&&m.Delivery==1,25,"first full physical delivery settles");Check(m.stones[0].InPlay,"AI draw legally qualifies beyond hog line");Note("First natural draw position="+m.stones[0].truck.body.position);
  // Explicitly seeded rule fixture between deliveries, followed by a genuine PhysX takeout.
  var guard=new Vector3(4,.3f,CurlingRules.Hog+4.5f);m.stones[0].Restore(guard,Quaternion.identity,false,false);m.setup.players[1].source=BowlingSource.Keyboard;yield return Wait(()=>m.Delivery==1&&m.Phase==CurlingPhase.Approach,4,"protected-guard snapshot");m.Current.truck.body.position=new Vector3(4,.38f,-2);m.Current.truck.body.rotation=Quaternion.identity;m.Current.truck.body.linearVelocity=Vector3.forward*20;Physics.SyncTransforms();yield return Wait(()=>m.Phase==CurlingPhase.Slide,8,"release before controlled takeout fixture");m.Current.truck.body.position=guard+new Vector3(0,.08f,-8);m.Current.truck.body.linearVelocity=Vector3.forward*20;Physics.SyncTransforms();yield return Wait(()=>m.Delivery==2&&m.Phase==CurlingPhase.DeliveryResult,30,"physical protected-guard removal and restoration");Note("Takeout after collision contacts="+m.PhysicalContacts+" guard="+m.stones[0].truck.body.position+" inPlay="+m.stones[0].InPlay+" shooter="+m.stones[1].truck.body.position);Check(m.GuardViolations==1&&!m.stones[1].InPlay&&m.stones[0].InPlay,"five-rock violation removes shooter and restores guard");Check(Vector3.Distance(m.stones[0].truck.body.position,guard)<.03f,"protected snapshot position restored after actual collision");Check(m.PhysicalContacts>0,"real truck-stone contact produced takeout fixture");Time.timeScale=1;Capture("guard-restored");yield return Delay(.2f);
  foreach(int size in new[]{1,4}){m.SetupScreen();m.teamA=m.teamB=size;m.option=size==1?0:1;m.NormalizeSetup();for(int i=0;i<m.setup.count;i++){m.setup.players[i].source=BowlingSource.AI;m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);}Check(m.StartMatch(),"complete "+size+"v"+size+" AI curling starts");Time.timeScale=4;yield return Wait(()=>m.Finished,550,"complete AI curling match "+size+"v"+size);if(m.Finished)yield return SportsResultsAcceptance.Capture(m,Check,folder+"/teams-"+size,slot=>(slot<m.teamA?0:1)==(m.scores[0]>m.scores[1]?0:1)?1:2,slot=>(double?)m.scores[slot<m.teamA?0:1],slot=>(slot<m.teamA?0:1)==(m.scores[0]>m.scores[1]?0:1));
 Check(m.EndsScored>=m.ConfiguredEnds&&m.scores[0]!=m.scores[1],"ends,16 alternating deliveries and final winner resolve "+size);Note("Curling "+size+"v"+size+" ends="+m.EndsScored+" score="+m.scores[0]+":"+m.scores[1]+" guardViolations="+m.GuardViolations+" physicalContactCallbacks="+m.PhysicalContacts);Time.timeScale=1;Capture("result-"+size);yield return Delay(.2f);}
  m.SetupScreen();Screen.SetResolution(1280,720,false);yield return Delay(.4f);Capture("setup-eight-720");yield return Delay(.2f);Screen.SetResolution(1920,1080,false);yield return Delay(.4f);Check(m.StartMatch(),"rematch retains eight-person rosters");yield return Delay(2);Capture("cab-1080");yield return Delay(.2f);SportsNavigation.FrontEnd();yield return Delay(.5f);Check(FindAnyObjectByType<SportsFrontEnd>()!=null,"Curling returns cleanly to collection");}
 void OnDestroy(){Application.logMessageReceived-=Log;}
#endif
}
}
